from heapq import heappush, heappop

def dijkstra(graph, start, end):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = [(0, start)]

    while queue:
        current_distance, current_node = heappop(queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(queue, (distance, neighbor))

    return distances[end]

def solve(n, p, M, m, complaints, radio_stations, interfering_pairs):
    interfering_stations = set()
    radio_power_pairs = {}

    for i in range(m):
        u, v = interfering_pairs[i]
        if u != v:
            interfering_stations.add(u)
            interfering_stations.add(v)
            if (u, v) not in radio_power_pairs:
                radio_power_pairs[(u, v)] = []
            radio_power_pairs[(u, v)].append(1)
            radio_power_pairs[(v, u)].append(1)

    for i in range(n):
        x, y = complaints[i]
        if (x, y) not in interfering_stations:
            if (x, y) in radio_power_pairs:
                radio_power_pairs[(x, y)].append(1)
            if (y, x) not in radio_power_pairs:
                radio_power_pairs[(y, x)] = []
            radio_power_pairs[(y, x)].append(1)

    stations = []
    for i in range(p):
        if i not in interfering_stations:
            if (i, i) not in radio_power_pairs:
                stations.append(i)

    if stations:
        graph = {station: {} for station in stations}

        for i in range(n):
            x, y = complaints[i]
            if x != y:
                graph[x][y] = 0
                graph[y][x] = 0

        for i in range(n):
            x, y = complaints[i]
            if (x, y) in radio_power_pairs:
                for power in radio_power_pairs[(x, y)]:
                    graph[x][y] = power
                    graph[y][x] = power

        f = n
        f_locations = []
        for station in stations:
            if dijkstra(graph, station, n) == n:
                f_locations.append(station)
                f -= 1

        f_locations = list(sorted(set(f_locations)))
        return len(f_locations), max(f_locations)

    return -1

