from collections import defaultdict

def find_shortest_cycle(graph, start, end):
    def find_shortest_path(graph, start, end):
        distance = defaultdict(lambda: float('inf'))
        distance[start] = 0
        visited = set([start])

        while visited:
            current = min(visited, key=lambda x: distance[x])
            visited.remove(current)

            for neighbor, weight in graph[current].items():
                if neighbor not in visited and distance[current] + weight < distance[neighbor]:
                    distance[neighbor] = distance[current] + weight

        return distance[end]

    def find_shortest_cycle_length(graph):
        shortest_path = float('inf')
        for start in range(1, n + 1):
            for end in range(1, n + 1):
                if start < end:
                    current_shortest_path = find_shortest_path(graph, start, end)
                    shortest_path = min(shortest_path, current_shortest_path)
        return shortest_path if shortest_path != float('inf') else -1

    n = len(graph)
    return find_shortest_cycle_length(graph)

