from collections import Counter

def count_palindromes(s):
    def expand_around_center(s):
        result = []
        for i in range(len(s)):
            result.append((i, j) for j in range(i, len(s)))  # left pointers
            result.append((i, j) for j in range(i + 1, len(s)))  # right pointers
        return result

    palindrome_pairs = Counter()
    pairs = Counter()

    for i in range(len(s)):
        for j in range(i, len(s)):
            s_part = s[i:j+1]
            if s_part == s_part[::-1]:
                palindrome_pairs[s_part] += 1

    for i in range(len(s)):
        word = s[:i]
        for j in pairwise(word):  # Use pairs() from Counter() to get distinct pairs
            if pairs.get(j, 0) > 0:
                pairs[j] -= 1

    for i in range(len(s)):
        word = s[i:]
        for j in pairwise(word):
            if j[::-1] in palindrome_pairs and palindrome_pairs[j[::-1]] > 0:
                palindrome_pairs[j[::-1]] -= 1
                pairs[j] += 1
            if j[::-1] in palindrome_pairs and palindrome_pairs[j[::-1]] == 0 and j[::-1] != word:
                palindrome_pairs[j[::-1]] = 1
                pairs[j] += 1

    return sum(pairs.values())

def pairwise(iterable):
