import heapq

def find_max_distance(n, m, roads, x):
    graph = [[] for _ in range(n+1)]
    for u, v, w in roads:
        graph[u].append((v, w*x))

    distances = {1: 0}
    heap = [(0, 1)]
    while heap:
        distance, node = heapq.heappop(heap)
        if node in distances:
            continue
        distances[node] = distance
        for neighbor, new_dist in graph[node]:
            if distance + new_dist <= distances.get(neighbor, float('inf')):
                heapq.heappush(heap, (distance + new_dist, neighbor))

    return distances[n]

