#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>
#include <string>
using namespace std;

typedef long long ll;
vector<ll> grid;
ll t, visited[50][50][1<<18];
vector<pair<ll,ll>> figs[99];

ll solve(ll k, ll n, vector<vector<ll>> grid) {
    ll ans = 0;
    memset(visited, 0, sizeof(visited));
    auto bit = [&](ll t) { return __builtin_popcountll(t - 1); };

    for (auto &f : figs[k]) {
        ll cnt = 0;
        for (auto & [x, y] : f) 
            if (1 << x == t && 1 << y == t) 
                cnt++;

        if (cnt % 2 == 0) 
            return 2000000000;

        if (n < 1000000000) {
            for (ll i = 0; i < 2 * k; i++) {
                for (ll j = 0; j < 2 * k; j++) {
                    if (abs(i - n) <= k && abs(j - n) <= k) 
                        visited[i][j] <<= 3;
                }
            }
        }

        ans += sqrt(2.0 * 1ll * (k * 1ll * k) * (ll)abs(n - k * k + k));
        ll maxval = bit(n);
        for (ll i = 0; i < 2 * k; i++) 
            for (ll j = 0; j < 2 * k; j++) 
                visited[i][j] <<= 3;
        for (ll i = 0; i < 2 * k; i++) 
            for (ll j = 0; j < 2 * k; j++) 
                if (bit(i) * bit(j) != maxval) visited[i][j]++;
        visited[n][n] *= maxval;
        for (ll i = 0; i < 2 * k; i++) {
            for (ll j = 0; j < 2 * k; j++) {
                if (visited[i][j] < 1) continue;
                if (abs(i - n) == 1 || abs(j - n) == 1) 
                    return 2000000000;
                else {
                    ll x = i + n, y = j;
                    for (int t = x; t; t >>= bit(t)) x ^= bit(t);
                    for (int t = y; t; t >>= bit(t)) y ^= bit(t);
                    if (abs(x - n) <= k && abs(y - n) <= k && abs(x - y) <= k) return (abs(x - n) == k && abs(y - n) == k && abs(x + y - n * 3) <= k);
                    else ans++;
                }
            }
        }
    }
    return ans;
}

