    int k;
    cin >> k;
    grid.resize(pow(2, k), vector<ll>(pow(2, k)));
    for (int i = 0; i < pow(2, k); i++) 
        for (int j = 0; j < pow(2, k); j++) cin >> grid[i][j];
    cin >> t;
    for (int i = 0; i < t; i++) {
