def next_permutation(arr):
    n = len(arr)
    i = n - 1
    while i > 0 and arr[i-1] >= arr[i]:
        i -= 1
    if i <= 0:
        return -1
    j = i
    while j < n and arr[j] < arr[i-1]:
        j += 1
    arr[i-1], arr[j-1] = arr[j-1], arr[i-1]
    arr[i:] = reversed(arr[i:])
    return arr

def update_array(arr, i, x):
    n = len(arr)
    a = arr[:i]
    b = arr[i+1:]
    a.append(x)
    next_a = next_permutation(a)
    if next_a == -1:
        b.append(x)
    else:
        b.append(next_a[i-1])
        b.reverse()
        b.extend(next_a[i:])
    arr = a + b
    return arr

