import math

def nearest_square(x):
    """Returns the nearest perfect square that is less than or equal to x"""
    return int(math.sqrt(x))

def find_min_moves(nums):
    """Finds the minimum number of moves to make the array good."""
    min_index = 0
    for i in range(1, len(nums)):
        if nums[i] != nums[i-1]:
            nums[min_index+1:i+1] = [nearest_square(nums[min_index])] * (i-min_index)
            min_index = i
    if nums:
        nums[min_index+1:] = [nearest_square(nums[-1])] * (len(nums)-min_index-1)
    return len(nums) - 1

