def find_pairs(s):
    n = len(s)
    count = n * (n - 1) // 2
    start = set()
    d = {}
    for i in range(1, n):
        if s[:i] in d:
            start.add(d[s[:i]])
        d[s[:i]] = i
    for i in reversed(range(n - 1)):
        prev_start = start.pop()
        if i - (n - i >= prev_start):
            count -= n - i
        count -= (i - prev_start - 1) * 2
        if s[i:] in d:
            start.add(d[s[i:]])
        d[s[i:]] = len(range(i, n)) + len(start)
    return count // 2

