def find_rectangle(n, m):
    if n < m:
        n, m = m, n
    if n == 1 and m == 1:
        return 1
    if n == 1 and m > 1:
        return m
    if n > 1 and m == 1:
        return n
    for x in range(1, int(math.sqrt(n * m) + 1)):
        if is_square(x * x * x) and is_square(x * x + m - 1) and is_square(m * m * x):
            return x
    return -1

def generate_rectangle(x, n, m):
