import math
from collections import defaultdict

def find_gcd(a, b):
    if b == 0:
        return a
    return find_gcd(b, a % b)

def find_gcds(n, memo):
    if n in memo:
        return memo[n]
    gcds = set()
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            gcds.add(i)
            if i != n // i:
                gcds.add(n // i)
    memo[n] = gcds
    return gcds

def compute_distance_sums(n):
    memo = {}
    result = 0

    for u in range(2, n):
        v = 1
        total_sum = 0
        gcds = find_gcds(v, memo)
        for g in gcds:
            total_sum += g * (u // g - 1)
        for g in gcds:
            for step in range(2, int(math.sqrt(g * u)) + 1):
                if g * u % (step * step) == 0:
                    total_sum -= step
        result += total_sum
        for gcd in gcds:
            memo[u] = memo.get(u, 0) + total_sum

    return result

