import sys
import heapq

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
    return distances

def adjust_paths(graph, x, fields, target):
    adjusted_graph = {}
    for node in fields:
        adjusted_paths = {neighbor: new_weight for neighbor, new_weight in graph[node].items()}
        max_increase = float('-inf')
        min_time = float('infinity')
        for neighbor, weight in adjusted_paths.items():
            adjusted_graph[neighbor] = (weight + x, max(weight + x - 1, graph[node][neighbor]))
            if new_weight + x > max_increase:
                max_increase = new_weight + x
            if distance[neighbor] + graph[node][neighbor] < min_time:
                min_time = distance[neighbor] + graph[node][neighbor]
        adjusted_graph[node] = (graph[node][target] + 1, max_increase)
    return adjusted_graph

def main():
