def distance_graph_length(n):
    """Calculate the sum of distances between all pairs of vertices in a graph."""
    memo = {}
    def dp(i, j):
        if i == j:
            return 0
        if (i, j) in memo:
            return memo[(i, j)]
        memo[(i, j)] = i + dp(i, j-1)
        if j > i:
            memo[(i, j)] += gcd(i, j)
        return memo[(i, j)]

