from bisect import bisect_left

def find_closest_to_max(a, n):
    idx = bisect_left(a, max(a, 0))
    diff = n - idx
    if diff < 0:
        return 0
    if idx >= len(a) or a[idx] == 0:
        return diff
    ans = diff - 1
    for i in range(idx, len(a)):
        if a[i] >= 0:
            ans += diff - i + 1
            break
    return ans

def count_tsetso_subarrays(a, l, r):
    n = len(a)
    count = 0
    max_left = [0] * n
    for i in range(n - 1, l - 1, -1):
        max_left[i] = max(a[i], max_left[i + 1])
    max_right = [0] * n
    for i in range(r, n - 1):
        max_right[i] = max(a[i], max_right[i + 1])
    for i in range(l - 1, r):
        if a[i] == 1:
            continue
        if max_right[i] * max_left[i] == a[i]:
            count += find_closest_to_max(a[i + 1:], r - i - 1) + find_closest_to_max(a[i + 1:], n - i - 1) - 1
    return count

