def find_next_arrangement(possible, seniority_from, seniority_to):
    status = [1] * len(possible)
    possible.sort()  # All arrangements are listed in this manner
    for i, j in seniority_from:
        idx = bisect.bisect_right(possible, i)
        if idx == len(possible):
            return "The times have changed"
        status[possible.index(min(possible[idx:], key=lambda x: x > j))] = 0
    for i, j in seniority_to:
        idx = bisect.bisect_right(possible, i)
        if idx == len(possible):
            return "The times have changed"
        status[possible.index(max(possible[idx:], key=lambda x: x < j))] = 0
    count = 0
    for i in status:
        if i:
            count += 1
    if count != len(possible):
        return "The times have changed"
    return ''.join(map(str, possible))

