def dijkstra(graph, start, goal, cap, cap_inefficient, time_limit):
    # Implement Dijkstra's algorithm
    # Update the maximum possible time for each edge
    max_time = {}
    nodes = len(graph)
    for node in range(nodes):
        max_time[node] = float('inf')
    distance = [float('inf')] * (2*nodes)
    parent = [-1] * (2*nodes)
    distance[start] = 0

    while start != goal:
        minimum = float('inf')
        previous = None
        for i in range(2*nodes):
            if distance[i] < minimum and max_time[i] <= time_limit:
                minimum = distance[i]
                previous = i
        for i in range(2*nodes):
            if distance[i] == minimum:
                if graph[i-source][(i-source+1)%2].weight + graph[previous-source-1][(i-source+1)%2].weight > cap or (
                        cap_inefficient and graph[i-source][source].capacity > ((cap_inefficient * graph[i-source][source].weight) // graph[previous-source-1][source].weight)):
                    continue
                temp = minimum + graph[i-source][(i-source+1)%2].weight
                if temp < distance[i]:
                    distance[i] = temp
                    parent[i] = previous
        start = previous
    if distance[goal + source-start] == float('inf'):
        return -1
    path = []
    repeat = 1
    while goal + start != goal + ((goal + start - source) % 2) + (repeat % 2):
        if parent[goal + start+repeat-1] != -1:
            path.append(graph[parent[goal + start+repeat-1] + source-1][start+repeat-1].weight)
            repeat += 1
    if path:
        time = distance[goal + start]
    else: 
        time = distance[goal + (start % 2)]
    return time

