from collections import defaultdict

def find_min_cycle_length(edges, n, m):
    edge_start = defaultdict(list)
    for i in range(m):
        u, v, w = map(lambda x: int(x) - 1, edges[i])
        edge_start[u].append(v, w)
        edge_start[v].append(u, w)

    def dfs(u, length, path):
        if length > 3:
            if path[-1] != 0:
                return
            length -= len(path)
            path = []
            return True
        if any(dfs(x[0], length - 1, path + [w]) for x, w in edge_start[u]):
            path = [w]
            return True
        b = False
        for v, w in edge_start[u]: 
            if v != -1:
                dfs(v, length - 1, [w] + path)
                b |= w != length - 1
        return b

    answer = -1
    for _ in range(n):
        for w in range(m):
            if u := edge_start[0].pop():
                answer = dfs(u, w + 1, [0]) or answer
    return answer

