                if u % divisor == 0 and v % divisor == 0:
                    common_divisor_squared += divisor**2
            if common_divisor_squared:
                distance = int(math.sqrt(common_divisor_squared))
            distance_sum += distance

    return distance_sum

t = int(input())
for _ in range(t):
    n = int(input())
    print(calculate_distance_sum(n))
